<?php
// Original pickup queue design with real pickup orders and collection recording.
use App\Services\Workspace;
use App\UI\LiveForm as F;
use App\UI\OrderStatus as S;
use App\UI\UI as U;

$live = Workspace::get()->load(static fn (Workspace $w): array => $w->queue());
if (isset($live['error'])): ?><?= U::heading('Pickup queue') ?><section class="panel p-6" role="alert"><?= U::e($live['error']) ?></section><?php return; endif;
$orders = array_values(array_filter(array_merge($live['queue'], $live['preparing'], $live['ready'], $live['awaiting_completion']), fn($o) => $o['fulfillment'] === 'pickup'));
$by = fn(array $statuses) => (string) count(array_filter($orders, fn($o) => in_array($o['status'], $statuses, true)));
?>
<?= U::heading('Pickup queue','Prepare water for collection at '.$info['caption'].'.') ?>
<div class="mb-4 grid grid-cols-2 gap-3 xl:grid-cols-3 max-xl:[&>:last-child:nth-child(odd)]:col-span-2"><?= U::stat('Pickup orders',(string)count($orders),'store','blue','Collected at the station','Total') ?><?= U::stat('Waiting',$by(['pending','confirmed','preparing']),'clock','amber','Confirmed, not yet refilled','Confirmed') ?><?= U::stat('Ready for pickup',$by(['ready']),'check','green','Customer can collect now','Ready') ?></div>
<p class="mb-4 flex items-center gap-2 rounded-xl border border-line bg-foam px-3.5 py-2.5 text-sm"><?= U::icon('shield','size-4 shrink-0 text-water') ?>Customers are notified at each step. Record the cash received when they collect; it counts as verified at once, then complete the order.</p>
<section class="panel p-4 md:p-5"><div class="mb-4 grid gap-3 sm:grid-cols-2"><?= U::field('Search pickups','pickup-search','','search',['icon'=>'search','data-search'=>'pickup-orders','placeholder'=>'Order or customer']) ?><?= U::select('Pickup status','pickup-status',['all'=>'All statuses','Confirmed'=>'Confirmed','Preparing'=>'Preparing','Ready for pickup'=>'Ready for pickup','Picked up'=>'Picked up'],'all',['data-filter-target'=>'pickup-orders']) ?></div>
<div class="overflow-x-auto"><table id="pickup-orders" class="data-table"><thead><tr><?php foreach(['Order','Customer','Containers','Requested','Status','Actions'] as $h): ?><th><?= $h ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($orders as $o): $f = ['order_id' => $o['id'], 'expected_version' => $o['version'], 'back' => '/station-admin/pickups']; $label = S::label($o['status'], 'pickup'); ?><tr data-search-row data-filter-value="<?= U::e($label) ?>"><td class="font-semibold"><?= U::e($o['order_no']) ?></td><td><?= U::e($o['customer_name'] ?? '') ?><p class="flex items-center gap-1 text-xs text-muted"><?= U::icon('credit','size-3.5') ?>Cash on pickup · <?= S::pesos($o['total_centavos']) ?></p></td><td><?= (int) $o['total_units'] ?></td><td><span class="inline-flex items-center gap-1.5"><?= U::icon('clock','size-4 text-muted') ?><?= U::e($o['schedule_mode'] === 'scheduled' ? S::time($o['requested_at'], 'M j, g:i A') : S::time($o['created_at'], 'g:i A')) ?></span></td><td><?= U::badge($label, S::tone($o['status'])) ?></td><td><div class="flex flex-wrap items-center gap-2">
<?php if (in_array($o['status'], ['pending','confirmed'], true)): ?><?= F::button('/station-admin/orders/start', $f, 'Start preparing', 'secondary', 'check') ?>
<?php elseif ($o['status'] === 'preparing'): ?><?= F::button('/station-admin/orders/ready', $f, 'Mark ready', 'secondary', 'check') ?>
<?php elseif ($o['status'] === 'ready'): ?><?= F::open('/station-admin/pickups/collect', $f, ['class' => 'flex flex-wrap items-center gap-1']) ?><input class="field w-24 py-1 text-sm" name="tendered" inputmode="decimal" required pattern="\d{1,7}(\.\d{1,2})?" placeholder="<?= U::e(number_format($o['total_centavos'] / 100, 2, '.', '')) ?>" aria-label="Cash received for <?= U::e($o['order_no']) ?>"><input class="field w-16 py-1 text-sm" name="empties" type="number" min="0" max="9999" value="<?= (int) $o['total_units'] ?>" required aria-label="Empty containers returned"><?= U::btn('Confirm collection','','primary','store',['type'=>'submit','class'=>'btn-sm','data-confirm'=>'Record this pickup as collected and paid?']) ?></form>
<?php endif ?><?= U::btn('View','/station-admin/orders?order='.$o['id'],'ghost','eye',['class'=>'btn-sm']) ?></div></td></tr><?php endforeach; ?></tbody></table><p data-empty <?= $orders === [] ? '' : 'hidden' ?> class="p-5 muted"><?= $orders === [] ? 'No pickup orders right now.' : 'No pickups match your search.' ?></p></div></section>
